import { EditorContent } from "@tiptap/react";

import { useRichTextEditorContext } from "./rte-context";
import type { RichTextEditorContentProps } from "./types";
import { cn } from "./ui/utils";

export const Content = ({
  children,
  className,
}: RichTextEditorContentProps) => {
  const { editor, preset, variant } = useRichTextEditorContext();

  return (
    <div className="relative">
      <EditorContent
        editor={editor}
        className={cn(
          "rte-content editorcn-content w-full",
          variant === "default" &&
            "rounded-lg border border-(--rte-hairline) bg-[var(--card,var(--background))]",
          className
        )}
        data-preset={preset}
        spellCheck={false}
      />
      {children}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { createContext, useContext } from "react";

import type { RichTextEditorIcons } from "./icon-types";
import type { RichTextEditorLabels } from "./labels";
import type { RichTextEditorPreset, RichTextEditorVariant } from "./types";
import type { TooltipHandle } from "./ui/tooltip";

interface RichTextEditorContextValue {
  editor: Editor | null;
  labels: RichTextEditorLabels;
  icons: RichTextEditorIcons;
  variant: RichTextEditorVariant;
  preset: RichTextEditorPreset;
  editable: boolean;
  tooltip: TooltipHandle;
}

export const RichTextEditorContext =
  createContext<RichTextEditorContextValue | null>(null);

export const useRichTextEditorContext = (): RichTextEditorContextValue => {
  const context = useContext(RichTextEditorContext);
  if (!context) {
    throw new Error(
      "useRichTextEditorContext must be used within RichTextEditor"
    );
  }
  return context;
};

import { useContext } from "react";

import { RichTextEditorContext } from "./rte-context";
import type {
  RichTextEditorControlsGroupProps,
  RichTextEditorVariant,
} from "./types";
import { cn } from "./ui/utils";

const SEPARATOR =
  "[.rte-controls-group+&]:before:w-px [.rte-controls-group+&]:before:shrink-0 [.rte-controls-group+&]:before:bg-border [.rte-controls-group+&]:before:content-[''] [.rte-controls-group+&]:data-line-start:before:invisible";

const BUTTON =
  "[&>button]:border-none [&>button]:bg-transparent [&>button]:transition-[background-color,color] [&>button]:duration-150 [&>button]:ease-[ease-out] [&>button:focus-visible]:outline-2 [&>button:focus-visible]:outline-offset-1 [&>button:focus-visible]:outline-ring/50 [&>button:focus-visible]:outline-solid";

const variantClasses: Record<RichTextEditorVariant, string> = {
  compact: `${SEPARATOR} [.rte-controls-group+&]:before:mx-0.5 [.rte-controls-group+&]:before:h-3.5 ${BUTTON} [&>button]:h-7 [&>button]:min-w-7 [&>button]:rounded-sm [&>button]:text-muted-foreground [&>button:hover]:bg-muted [&>button:hover]:text-foreground [&>button[aria-pressed=true]]:bg-muted [&>button[aria-pressed=true]]:text-foreground [&>button[data-state=on]]:bg-muted [&>button[data-state=on]]:text-foreground`,
  default: `gap-0.5 ${SEPARATOR} [.rte-controls-group+&]:before:mx-1 [.rte-controls-group+&]:before:h-4 ${BUTTON} [&>button]:h-8 [&>button]:min-w-8 [&>button]:rounded-md [&>button]:text-foreground [&>button:disabled]:cursor-not-allowed [&>button:disabled]:opacity-40 [&>button:hover:not(:disabled)]:bg-foreground/5 [&>button:hover:not(:disabled)]:text-foreground [&>button[aria-pressed=true]]:bg-foreground/8 [&>button[aria-pressed=true]]:text-foreground [&>button[data-state=on]]:bg-foreground/8 [&>button[data-state=on]]:text-foreground`,
  subtle: `${SEPARATOR} [.rte-controls-group+&]:before:mx-1 [.rte-controls-group+&]:before:h-4 ${BUTTON} [&>button]:h-8 [&>button]:min-w-8 [&>button]:rounded-md [&>button]:text-muted-foreground [&>button:hover]:bg-muted [&>button:hover]:text-foreground [&>button[aria-pressed=true]]:bg-muted [&>button[aria-pressed=true]]:text-foreground [&>button[data-state=on]]:bg-muted [&>button[data-state=on]]:text-foreground`,
};

export const ControlsGroup = ({
  children,
  className,
}: RichTextEditorControlsGroupProps) => {
  const variant = useContext(RichTextEditorContext)?.variant;

  return (
    <div
      className={cn(
        "rte-controls-group flex items-center empty:hidden",
        variant && variantClasses[variant],
        className
      )}
    >
      {children}
    </div>
  );
};

import { useEffect, useMemo, useRef, useState } from "react";

import { useRichTextEditorContext } from "./rte-context";
import type { RichTextEditorFooterProps } from "./types";
import { cn } from "./ui/utils";

export const Footer = ({
  children,
  className,
  sticky = false,
  stickyOffset = 0,
  showWordCount = false,
  wordCountClassName,
  wordCountFormatter,
}: RichTextEditorFooterProps) => {
  const { editor, variant } = useRichTextEditorContext();
  const [, forceUpdate] = useState(0);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (!editor || !showWordCount) {
      return;
    }

    const scheduleUpdate = () => {
      if (rafRef.current !== null) {
        return;
      }
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = null;
        forceUpdate((t) => t + 1);
      });
    };

    const handleTransaction = ({
      transaction,
    }: {
      transaction: { docChanged: boolean };
    }) => {
      if (transaction.docChanged) {
        scheduleUpdate();
      }
    };

    editor.on("transaction", handleTransaction);
    scheduleUpdate();

    return () => {
      editor.off("transaction", handleTransaction);
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [editor, showWordCount]);

  const wordCount = useMemo(() => {
    if (!editor || !showWordCount) {
      return null;
    }

    const count = (editor.storage as unknown as Record<string, unknown>)
      .characterCount as
      | { words: () => number; characters: () => number }
      | undefined;
    const words = count?.words() ?? 0;
    const characters = count?.characters() ?? 0;

    return { characters, words };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    editor,
    showWordCount,
    wordCountFormatter,
    editor?.state.doc.content.size,
  ]);

  if (!showWordCount && !children) {
    return null;
  }

  return (
    <div
      className={cn(
        "rte-footer z-1 flex min-h-9 flex-wrap items-center justify-between gap-2 rounded-es-[calc(var(--radius)+3px)] rounded-ee-[calc(var(--radius)+3px)] border-t border-(--rte-hairline) bg-(--rte-strip) px-3 py-1.5 text-[0.75rem] text-muted-foreground",
        variant !== "default" && `rte-footer--${variant}`,
        variant === "default" &&
          "min-h-8 rounded-none border-t-0 bg-transparent px-2 pt-1 pb-0",
        variant === "compact" &&
          "rounded-none last:rounded-es-[calc(var(--radius)-1px)] last:rounded-ee-[calc(var(--radius)-1px)]",
        sticky &&
          "sticky bottom-0 bg-[color-mix(in_srgb,var(--rte-strip)_80%,transparent)] backdrop-blur-lg",
        className
      )}
      data-sticky={sticky ? "" : undefined}
      style={sticky ? { bottom: stickyOffset } : undefined}
    >
      {showWordCount && wordCount && (
        <span
          className={cn(
            "rte-footer-word-count inline-flex items-center gap-1.5 text-[0.75rem] whitespace-nowrap",
            wordCountClassName
          )}
        >
          {wordCountFormatter ? (
            wordCountFormatter(wordCount)
          ) : (
            <>
              <span className="rte-footer-word-count-stat inline-flex items-baseline gap-1">
                <span className="rte-footer-word-count-number font-medium text-foreground tabular-nums">
                  {wordCount.words}
                </span>
                <span className="rte-footer-word-count-unit text-muted-foreground">
                  words
                </span>
              </span>
              <span
                className="rte-footer-word-count-separator size-[3px] shrink-0 rounded-full bg-[color-mix(in_srgb,var(--muted-foreground)_45%,transparent)]"
                aria-hidden="true"
              />
              <span className="rte-footer-word-count-stat inline-flex items-baseline gap-1">
                <span className="rte-footer-word-count-number font-medium text-foreground tabular-nums">
                  {wordCount.characters}
                </span>
                <span className="rte-footer-word-count-unit text-muted-foreground">
                  characters
                </span>
              </span>
            </>
          )}
        </span>
      )}
      {children}
    </div>
  );
};

import { useEffect, useMemo, useState } from "react";

import { BubbleMenu } from "./bubble-menu/index";
import {
  RichTextEditorControl,
  RichTextEditorTooltip,
} from "./controls/rte-control";
import * as controls from "./controls/rte-controls";
import { LinkControl } from "./controls/rte-link-control";
import { TwitterEmbedControl } from "./controls/rte-twitter-control";
import { YouTubeEmbedControl } from "./controls/rte-youtube-control";
import { DEFAULT_ICONS } from "./icons";
import { DEFAULT_LABELS } from "./labels";
import { Content } from "./rte-content";
import { RichTextEditorContext } from "./rte-context";
import { ControlsGroup } from "./rte-controls-group";
import { Footer } from "./rte-footer";
import { Toolbar } from "./rte-toolbar";
import type { RichTextEditorProps } from "./types";
import {
  createTooltipHandle,
  TooltipHost,
  TooltipProvider,
} from "./ui/tooltip";
import { cn } from "./ui/utils";

const RichTextEditorRoot = ({
  editor,
  children,
  className,
  labels,
  icons,
  variant = "default",
  preset = "document",
  editable = true,
}: RichTextEditorProps) => {
  const mergedLabels = useMemo(
    () => ({ ...DEFAULT_LABELS, ...labels }),
    [labels]
  );

  const mergedIcons = useMemo(() => ({ ...DEFAULT_ICONS, ...icons }), [icons]);
  const [tooltip] = useState(createTooltipHandle);

  useEffect(() => {
    if (editor && editor.isEditable !== editable) {
      editor.setEditable(editable);
    }
  }, [editor, editable]);

  return (
    <RichTextEditorContext.Provider
      value={{
        editable,
        editor,
        icons: mergedIcons,
        labels: mergedLabels,
        preset,
        tooltip,
        variant,
      }}
    >
      <div
        className={cn(
          "rte-root relative rounded-xl border border-(--rte-hairline) bg-background [--rte-float-shadow:0_8px_30px_-12px_rgb(0_0_0/0.15)] [--rte-hairline:color-mix(in_srgb,var(--border)_60%,transparent)] [--rte-strip:color-mix(in_srgb,var(--muted)_50%,var(--background))] [transition:border-color_150ms_ease-out] [&_.rte-editor-icon]:size-4 [&_.rte-editor-icon]:shrink-0",
          variant === "default" && "bg-(--rte-strip) p-1",
          variant !== "default" && `rte-root--${variant}`,
          variant === "compact" &&
            "rounded-lg data-[variant=compact]:[&_.rte-editor-icon]:size-3.5",
          className
        )}
        data-variant={variant}
      >
        <TooltipProvider>
          <TooltipHost handle={tooltip} side="bottom">
            {children}
          </TooltipHost>
        </TooltipProvider>
      </div>
    </RichTextEditorContext.Provider>
  );
};

export const RichTextEditor = Object.assign(RichTextEditorRoot, {
  AlignCenter: controls.AlignCenterControl,
  AlignJustify: controls.AlignJustifyControl,
  AlignLeft: controls.AlignLeftControl,
  AlignRight: controls.AlignRightControl,
  Blockquote: controls.BlockquoteControl,
  Bold: controls.BoldControl,
  BubbleMenu,
  BulletList: controls.BulletListControl,
  ClearFormatting: controls.ClearFormattingControl,
  Code: controls.CodeControl,
  CodeBlock: controls.CodeBlockControl,
  Content,
  Control: RichTextEditorControl,
  ControlsGroup,
  Footer,
  H1: controls.H1Control,
  H2: controls.H2Control,
  H3: controls.H3Control,
  H4: controls.H4Control,
  H5: controls.H5Control,
  H6: controls.H6Control,
  Highlight: controls.HighlightControl,
  Hr: controls.HrControl,
  Italic: controls.ItalicControl,
  Link: LinkControl,
  OrderedList: controls.OrderedListControl,
  Redo: controls.RedoControl,
  Strikethrough: controls.StrikethroughControl,
  Subscript: controls.SubscriptControl,
  Superscript: controls.SuperscriptControl,
  Toolbar,
  Tooltip: RichTextEditorTooltip,
  TwitterEmbed: TwitterEmbedControl,
  Underline: controls.UnderlineControl,
  Undo: controls.UndoControl,
  Unlink: controls.UnlinkControl,
  YouTubeEmbed: YouTubeEmbedControl,
});

import { useLayoutEffect, useRef } from "react";

import { useRichTextEditorContext } from "./rte-context";
import type { RichTextEditorToolbarProps } from "./types";
import { cn } from "./ui/utils";

// Groups draw their separator before themselves, so when the toolbar wraps,
// the first group on each new row would start with a stray separator. CSS
// can't tell which flex item starts a line, so mark those groups here. The
// marker only makes the separator invisible (it keeps its width), so marking
// never changes the layout it was computed from and can't oscillate.
const GROUPS = ":scope > .rte-controls-group";

const useMarkLineStarts = (enabled: boolean) => {
  const ref = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const toolbar = ref.current;
    if (!enabled || !toolbar || typeof ResizeObserver === "undefined") {
      return;
    }
    const mark = () => {
      let previous: DOMRect | null = null;
      for (const group of toolbar.querySelectorAll<HTMLElement>(GROUPS)) {
        if (group.getClientRects().length === 0) {
          continue;
        }
        const rect = group.getBoundingClientRect();
        const startsLine = previous !== null && rect.top >= previous.bottom - 1;
        group.toggleAttribute("data-line-start", startsLine);
        previous = rect;
      }
    };
    // Watch the toolbar and every group, so controls appearing or resizing
    // inside a group re-mark rows even when the toolbar's size stays the same.
    const resize = new ResizeObserver(mark);
    const observeAll = () => {
      resize.disconnect();
      resize.observe(toolbar);
      for (const group of toolbar.querySelectorAll<HTMLElement>(GROUPS)) {
        resize.observe(group);
      }
    };
    // Only child list changes: the marker attribute never re-triggers this.
    const mutation = new MutationObserver(() => {
      observeAll();
      mark();
    });
    mutation.observe(toolbar, { childList: true });
    observeAll();
    mark();
    return () => {
      resize.disconnect();
      mutation.disconnect();
    };
  }, [enabled]);

  return ref;
};

export const Toolbar = ({
  children,
  className,
  sticky,
  stickyOffset = 0,
}: RichTextEditorToolbarProps) => {
  const { variant, editable } = useRichTextEditorContext();
  const ref = useMarkLineStarts(editable);

  if (!editable) {
    return null;
  }

  return (
    <div
      ref={ref}
      className={cn(
        "rte-toolbar top-[var(--rte-sticky-offset,0px)] z-1 flex flex-wrap items-center justify-center gap-1 rounded-ss-[calc(var(--radius)+3px)] rounded-se-[calc(var(--radius)+3px)] border-b border-(--rte-hairline) bg-(--rte-strip) px-2 py-1.5 [transition:background-color_150ms_ease-out]",
        "[@media(max-width:640px)]:justify-start [@media(max-width:640px)]:flex-nowrap [@media(max-width:640px)]:overflow-x-auto [@media(max-width:640px)]:[--rte-toolbar-fade-end:1.5rem] [@media(max-width:640px)]:[-ms-overflow-style:none] [@media(max-width:640px)]:[-webkit-overflow-scrolling:touch] [@media(max-width:640px)]:[mask-image:linear-gradient(to_right,transparent,black_var(--rte-toolbar-fade-start),black_calc(100%-var(--rte-toolbar-fade-end)),transparent)] [@media(max-width:640px)]:[scrollbar-width:none] [@media(max-width:640px)]:[&::-webkit-scrollbar]:hidden [@media(max-width:640px)]:supports-[animation-timeline:scroll()]:[--rte-toolbar-fade-end:0px] [@media(max-width:640px)]:supports-[animation-timeline:scroll()]:animate-rte-toolbar-fade [@media(max-width:640px)]:supports-[animation-timeline:scroll()]:[animation-timeline:scroll(self_inline)]",
        variant !== "default" && `rte-toolbar--${variant}`,
        variant === "default" &&
          "gap-1 rounded-none border-b-0 bg-transparent px-0 pt-0 pb-1",
        variant === "subtle" && "gap-1 px-1.5 py-1",
        variant === "compact" &&
          "gap-0.5 rounded-none px-1.5 py-1 first:rounded-ss-[calc(var(--radius)-1px)] first:rounded-se-[calc(var(--radius)-1px)]",
        sticky &&
          "sticky bg-[color-mix(in_srgb,var(--rte-strip)_80%,transparent)] backdrop-blur-lg",
        sticky &&
          variant === "default" &&
          "-mx-1 -mt-1 rounded-ss-[calc(var(--radius)+3px)] rounded-se-[calc(var(--radius)+3px)] bg-[color-mix(in_srgb,var(--rte-strip)_85%,transparent)] p-1",
        className
      )}
      data-sticky={sticky ? "" : undefined}
      style={sticky ? { top: stickyOffset } : undefined}
    >
      {children}
    </div>
  );
};

