import { isTextSelection } from "@tiptap/core";
import type { Editor } from "@tiptap/react";
import { BubbleMenu as TiptapBubbleMenu } from "@tiptap/react/menus";
import { useCallback } from "react";

import { RteSeparator } from "../ui";
import { ColorSelector } from "./color-selector";
import { TextButtons, getTextItems } from "./text-buttons";

export interface BubbleMenuProps {
  editor: Editor | null;
}

export const BubbleMenu = ({ editor }: BubbleMenuProps) => {
  const shouldShow = useCallback(
    ({
      editor: ed,
      state,
    }: {
      editor: Editor;
      state: { selection: { empty: boolean } };
    }) => {
      const { selection } = state;
      if (!ed.isEditable) {
        return false;
      }
      if (selection.empty || ed.isActive("codeBlock")) {
        return false;
      }
      if (!selection.empty && !isTextSelection(selection)) {
        return false;
      }
      return true;
    },
    []
  );

  if (!editor) {
    return null;
  }

  const hasText = getTextItems(editor).length > 0;
  const hasColor = editor.extensionManager.extensions.some(
    (ext) => ext.name === "color" || ext.name === "highlight"
  );

  if (!(hasText || hasColor)) {
    return null;
  }

  return (
    <TiptapBubbleMenu
      className="z-50"
      editor={editor}
      options={{ offset: 8, placement: "top" }}
      shouldShow={shouldShow}
    >
      <div className="rte-bubble-menu flex h-10 animate-rte-bubble-pop-in items-center rounded-lg border border-[color-mix(in_srgb,var(--border)_60%,transparent)] bg-popover px-1 text-popover-foreground shadow-[0_8px_30px_-12px_rgb(0_0_0/0.15)]">
        {hasText && <TextButtons editor={editor} />}
        {hasText && hasColor && <RteSeparator />}
        {hasColor && <ColorSelector editor={editor} />}
      </div>
    </TiptapBubbleMenu>
  );
};

import type { Editor } from "@tiptap/react";
import { useState } from "react";

import {
  RteButton,
  RteColorSwatch,
  RteDropdown,
  RteDropdownDivider,
  RteIcon,
  RteOverlay,
} from "../ui";
import { useEditorState, shallowEqual } from "./utils";

type SwatchType = "text" | "highlight";

interface RecentColor {
  type: SwatchType;
  color: string;
  label: string;
}

const RECENT_KEY = "editorcn-editor-recent-colors";
const RECENT_LIMIT = 10;

const readRecentColors = (): RecentColor[] => {
  if (typeof window === "undefined") {
    return [];
  }
  try {
    const raw = window.localStorage.getItem(RECENT_KEY);
    if (!raw) {
      return [];
    }
    const parsed = JSON.parse(raw) as RecentColor[];
    return Array.isArray(parsed) ? parsed.slice(0, RECENT_LIMIT) : [];
  } catch {
    return [];
  }
};

const persistRecentColors = (recent: RecentColor[]): void => {
  try {
    window.localStorage.setItem(RECENT_KEY, JSON.stringify(recent));
  } catch {
    /* ignored */
  }
};

const TEXT_COLORS = [
  { color: "#0f172a", label: "Foreground" },
  { color: "#ef4444", label: "Red" },
  { color: "#f97316", label: "Orange" },
  { color: "#f59e0b", label: "Amber" },
  { color: "#22c55e", label: "Green" },
  { color: "#0ea5e9", label: "Sky" },
  { color: "#3b82f6", label: "Blue" },
  { color: "#6366f1", label: "Indigo" },
  { color: "#a855f7", label: "Purple" },
  { color: "#ec4899", label: "Pink" },
] as const;

const HIGHLIGHT_COLORS = [
  { color: "#fef08a", label: "Yellow" },
  { color: "#fed7aa", label: "Orange" },
  { color: "#fecaca", label: "Red" },
  { color: "#fbcfe8", label: "Pink" },
  { color: "#e9d5ff", label: "Purple" },
  { color: "#ddd6fe", label: "Violet" },
  { color: "#bfdbfe", label: "Blue" },
  { color: "#a5f3fc", label: "Cyan" },
  { color: "#99f6e4", label: "Teal" },
  { color: "#bbf7d0", label: "Green" },
] as const;

interface ColorChain {
  run(): boolean;
  setColor(color: string): ColorChain;
  setHighlight(attributes: { color: string }): ColorChain;
  unsetColor(): ColorChain;
  unsetHighlight(): ColorChain;
}

export const ColorSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const [recent, setRecent] = useState<RecentColor[]>(() => readRecentColors());

  const { highlightColor, textColor } = useEditorState(
    editor,
    (ed) => ({
      highlightColor: ed.isActive("highlight")
        ? (ed.getAttributes("highlight").color as string | undefined)
        : undefined,
      textColor: ed.isActive("textStyle")
        ? (ed.getAttributes("textStyle").color as string | undefined)
        : undefined,
    }),
    shallowEqual
  );

  const hasColor = editor.extensionManager.extensions.some(
    (ext) => ext.name === "color"
  );
  const hasHighlight = editor.extensionManager.extensions.some(
    (ext) => ext.name === "highlight"
  );

  const remember = (type: SwatchType, color: string, label: string): void => {
    setRecent((prev) => {
      const next = [
        { color, label, type },
        ...prev.filter((item) => !(item.type === type && item.color === color)),
      ].slice(0, RECENT_LIMIT);
      persistRecentColors(next);
      return next;
    });
  };

  const selectText = (color: string, label: string): void => {
    remember("text", color, label);
    if (textColor === color) {
      (editor.chain().focus() as unknown as ColorChain).unsetColor().run();
    } else {
      (editor.chain().focus() as unknown as ColorChain).setColor(color).run();
    }
  };

  const selectHighlight = (color: string, label: string): void => {
    remember("highlight", color, label);
    if (highlightColor === color) {
      (editor.chain().focus() as unknown as ColorChain).unsetHighlight().run();
    } else {
      (editor.chain().focus() as unknown as ColorChain)
        .setHighlight({ color })
        .run();
    }
  };

  if (!hasColor && !hasHighlight) {
    return null;
  }

  return (
    <div style={{ position: "relative" }}>
      <RteButton
        active={Boolean(textColor || highlightColor)}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
        title="Text color"
      >
        <RteIcon>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            className="rte-editor-icon"
          >
            <path d="M4 20h16" />
            <path d="m6 16 6-12 6 12" />
            <path d="M8 12h8" />
          </svg>
        </RteIcon>
      </RteButton>
      {open && (
        <>
          <RteOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <RteDropdown variant="color">
            {recent.length > 0 ? (
              <div className="rte-bubble-color-section flex flex-col gap-2">
                <span className="rte-bubble-color-label px-0.5 text-[0.75rem] leading-none font-medium text-muted-foreground">
                  Recently Used
                </span>
                <div className="rte-bubble-color-recent flex flex-wrap justify-center gap-1.5">
                  {recent.map((item) => (
                    <RteColorSwatch
                      key={`${item.type}-${item.color}`}
                      variant={item.type}
                      color={item.color}
                      label={item.label}
                      active={
                        item.type === "text"
                          ? textColor === item.color
                          : highlightColor === item.color
                      }
                      onSelect={() =>
                        item.type === "text"
                          ? selectText(item.color, item.label)
                          : selectHighlight(item.color, item.label)
                      }
                    />
                  ))}
                </div>
              </div>
            ) : null}
            {hasColor ? (
              <>
                {recent.length > 0 && <RteDropdownDivider />}
                <div className="rte-bubble-color-section flex flex-col gap-2">
                  <span className="rte-bubble-color-label px-0.5 text-[0.75rem] leading-none font-medium text-muted-foreground">
                    Text Color
                  </span>
                  <div className="rte-bubble-color-grid grid grid-cols-[repeat(5,1.5rem)] justify-center gap-1.5">
                    {TEXT_COLORS.map((item) => (
                      <RteColorSwatch
                        key={item.color}
                        variant="text"
                        color={item.color}
                        label={item.label}
                        active={textColor === item.color}
                        onSelect={() => selectText(item.color, item.label)}
                      />
                    ))}
                  </div>
                </div>
              </>
            ) : null}
            {hasHighlight ? (
              <>
                {(recent.length > 0 || hasColor) && <RteDropdownDivider />}
                <div className="rte-bubble-color-section flex flex-col gap-2">
                  <span className="rte-bubble-color-label px-0.5 text-[0.75rem] leading-none font-medium text-muted-foreground">
                    Highlight Color
                  </span>
                  <div className="rte-bubble-color-grid grid grid-cols-[repeat(5,1.5rem)] justify-center gap-1.5">
                    {HIGHLIGHT_COLORS.map((item) => (
                      <RteColorSwatch
                        key={item.color}
                        variant="highlight"
                        color={item.color}
                        label={item.label}
                        active={highlightColor === item.color}
                        onSelect={() => selectHighlight(item.color, item.label)}
                      />
                    ))}
                  </div>
                </div>
              </>
            ) : null}
          </RteDropdown>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";

import { RteButton, RteButtonGroup, RteIcon } from "../ui";
import { useEditorState, shallowEqual } from "./utils";

const Svg = ({
  children,
  strokeWidth = 2,
}: {
  children: React.ReactNode;
  strokeWidth?: number;
}) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={strokeWidth}
    strokeLinecap="round"
    strokeLinejoin="round"
    className="rte-editor-icon"
  >
    {children}
  </svg>
);

const Icon = ({ children }: { children: React.ReactNode }) => (
  <RteIcon>{children}</RteIcon>
);

interface TextSelectorResult {
  isBold: boolean;
  isItalic: boolean;
  isUnderline: boolean;
  isStrike: boolean;
  isCode: boolean;
}

interface ToggleableChain {
  run(): boolean;
  toggleBold(): ToggleableChain;
  toggleCode(): ToggleableChain;
  toggleItalic(): ToggleableChain;
  toggleStrike(): ToggleableChain;
  toggleUnderline(): ToggleableChain;
}

const textItems = [
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleBold().run(),
    icon: (
      <Icon>
        <Svg>
          <path d="M6 4h8a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z" />
          <path d="M6 12h9a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z" />
        </Svg>
      </Icon>
    ),
    isActive: (s: TextSelectorResult) => s.isBold,
    mark: "bold",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleItalic().run(),
    icon: (
      <Icon>
        <Svg>
          <line x1="19" y1="4" x2="10" y2="4" />
          <line x1="14" y1="20" x2="5" y2="20" />
          <line x1="15" y1="4" x2="9" y2="20" />
        </Svg>
      </Icon>
    ),
    isActive: (s: TextSelectorResult) => s.isItalic,
    mark: "italic",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleUnderline().run(),
    icon: (
      <Icon>
        <Svg>
          <path d="M6 4v6a6 6 0 0 0 12 0V4" />
          <line x1="4" y1="20" x2="20" y2="20" />
        </Svg>
      </Icon>
    ),
    isActive: (s: TextSelectorResult) => s.isUnderline,
    mark: "underline",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleStrike().run(),
    icon: (
      <Icon>
        <Svg>
          <path d="M16 4H9.5a3.5 3.5 0 0 0-2.9 5.4" />
          <path d="M14.5 14.6a3.5 3.5 0 0 1-2.9 5.4H8" />
          <line x1="4" y1="12" x2="20" y2="12" />
        </Svg>
      </Icon>
    ),
    isActive: (s: TextSelectorResult) => s.isStrike,
    mark: "strike",
  },
  {
    command: (e: Editor) =>
      (e.chain().focus() as unknown as ToggleableChain).toggleCode().run(),
    icon: (
      <Icon>
        <Svg>
          <polyline points="16 18 22 12 16 6" />
          <polyline points="8 6 2 12 8 18" />
        </Svg>
      </Icon>
    ),
    isActive: (s: TextSelectorResult) => s.isCode,
    mark: "code",
  },
];

export const getTextItems = (editor: Editor) =>
  textItems.filter((item) => Boolean(editor.schema.marks[item.mark]));

export const TextButtons = ({ editor }: { editor: Editor }) => {
  const editorState = useEditorState(
    editor,
    (ed) => ({
      isBold: ed.isActive("bold"),
      isCode: ed.isActive("code"),
      isItalic: ed.isActive("italic"),
      isStrike: ed.isActive("strike"),
      isUnderline: ed.isActive("underline"),
    }),
    shallowEqual
  );

  return (
    <RteButtonGroup>
      {getTextItems(editor).map((item) => (
        <RteButton
          key={item.mark}
          active={item.isActive(editorState)}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => item.command(editor)}
        >
          {item.icon}
        </RteButton>
      ))}
    </RteButtonGroup>
  );
};

import type { Editor } from "@tiptap/react";
import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T) => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);

  useEffect(() => {
    selectorRef.current = selector;
    isEqualRef.current = isEqual;
  });

  const snapshotRef = useRef<{ value: T }>({
    value: editor ? selector(editor) : (undefined as unknown as T),
  });

  const updateSnapshot = useCallback(() => {
    if (!editor) {
      return;
    }
    const next = selectorRef.current(editor);
    if (
      snapshotRef.current &&
      isEqualRef.current(snapshotRef.current.value, next)
    ) {
      return;
    }
    snapshotRef.current = { value: next };
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {
          // noop
        };
      }
      const update = () => {
        updateSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, updateSnapshot]
  );

  const getSnapshot = useCallback((): T => snapshotRef.current.value, []);

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
};

