const getYouTubeId = (url: string): string | null => {
  const clean = url.trim();
  const patterns = [
    /(?:youtube\.com\/watch\?v=)([a-zA-Z0-9_-]{11})/,
    /(?:youtu\.be\/)([a-zA-Z0-9_-]{11})/,
    /(?:youtube\.com\/embed\/)([a-zA-Z0-9_-]{11})/,
    /(?:youtube\.com\/shorts\/)([a-zA-Z0-9_-]{11})/,
    /(?:youtube\.com\/live\/)([a-zA-Z0-9_-]{11})/,
    /(?:youtube\.com\/v\/)([a-zA-Z0-9_-]{11})/,
    /(?:m\.youtube\.com\/watch\?v=)([a-zA-Z0-9_-]{11})/,
  ];
  for (const pattern of patterns) {
    const match = clean.match(pattern);
    if (match) {
      return match[1] ?? null;
    }
  }
  return /^[a-zA-Z0-9_-]{11}$/.test(clean) ? clean : null;
};

const YouTubeNodeView = (props: NodeViewProps) => {
  const { node, updateAttributes } = props;
  const rawSrc = node.attrs.src || "";
  const videoId = getYouTubeId(rawSrc) || rawSrc;
  let watchUrl: string | undefined;
  if (videoId) {
    watchUrl = videoId.startsWith("http")
      ? videoId
      : `https://www.youtube.com/watch?v=${videoId}`;
  }

  return (
    <ResizableNodeView
      {...props}
      lockAspect
      aspectRatio={16 / 9}
      minWidth={320}
      maxWidth={1200}
      videoSrc={rawSrc}
      watchUrl={watchUrl}
      onSrcChange={(newSrc) => updateAttributes({ src: newSrc })}
    >
      <iframe
        src={`https://www.youtube-nocookie.com/embed/${videoId}`}
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
        title="YouTube video"
        className="rte-embed-iframe"
      />
    </ResizableNodeView>
  );
};

export const YouTubeEmbed = Node.create({
  ...createAtomBlockMarkdownSpec({
    allowedAttributes: ["src", "width", "height", "align"],
    nodeName: "youtube",
    parseAttributes: (text) => {
      const attrs = parseAttributes(text);
      for (const key of ["width", "height"]) {
        if (key in attrs) {
          attrs[key] = Number(attrs[key]);
        }
      }
      return attrs;
    },
    requiredAttributes: ["src"],
  }),
  addAttributes() {
    return {
      align: {
        default: "center",
        parseHTML: (el: HTMLElement) => el.dataset.align || "center",
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-align": attrs.align,
        }),
      },
      height: {
        default: 315,
        parseHTML: (el: HTMLElement) =>
          el.dataset.height ? Number(el.dataset.height) : 315,
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-height": attrs.height,
        }),
      },
      src: {
        default: null,
        parseHTML: (el: HTMLElement) => el.dataset.src,
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-src": attrs.src,
        }),
      },
      width: {
        default: 560,
        parseHTML: (el: HTMLElement) =>
          el.dataset.width ? Number(el.dataset.width) : 560,
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-width": attrs.width,
        }),
      },
    };
  },
  addCommands() {
    return {
      setYouTubeEmbed:
        (src: string) =>
        ({ commands }) =>
          commands.insertContent({
            attrs: { src },
            type: "youtube",
          }),
    };
  },
  addInputRules() {
    return [
      nodeInputRule({
        find: /https?:\/\/(?:www\.|m\.)?(?:youtube\.com|youtu\.be)\/(?:watch\?v=|embed\/|shorts\/|live\/|v\/)?([a-zA-Z0-9_-]{11})/,
        getAttributes: (match: RegExpMatchArray) => ({ src: match[0] }),
        type: this.type,
      }),
    ];
  },
  addNodeView() {
    return ReactNodeViewRenderer(YouTubeNodeView);
  },
  atom: true,
  draggable: true,
  group: "block",
  name: "youtube",
  parseHTML() {
    return [{ tag: 'div[data-type="youtube"]' }];
  },
  renderHTML({ node }: { node: { attrs: Record<string, unknown> } }) {
    return [
      "div",
      {
        "data-align": node.attrs.align,
        "data-height": node.attrs.height,
        "data-src": node.attrs.src,
        "data-type": "youtube",
        "data-width": node.attrs.width,
      },
    ];
  },
});

