  (
    {
      className,
      variant = "default",
      size = "default",
      render,
      children,
      ...props
    },
    ref
  ) => {
    const slot = withRender({ children, render });
    const classes = cn(buttonVariants({ className, size, variant }));
    if (slot.asChild) {
      const slotProps = {
        ...props,
        type: props.type ?? (render?.type === "button" ? "button" : undefined),
      };
      return (
        <Slot.Root
          ref={ref}
          data-slot="button"
          className={classes}
          {...slotProps}
        >
          {slot.children}
        </Slot.Root>
      );
    }
    return (
      <button
        ref={ref}
        data-slot="button"
        className={classes}
        {...props}
        type={props.type ?? "button"}
      >
        {slot.children}
      </button>
    );
  }
);
