        top: item.offsetTop,
        width: item.offsetWidth,
      });
    }, []);

    const handleMouseOver = useCallback(
      (event: React.MouseEvent<HTMLDivElement>) => {
        handleItemEnter(event.target);
      },
      [handleItemEnter]
    );

    const handleFocus = useCallback(
      (event: React.FocusEvent<HTMLDivElement>) => {
        handleItemEnter(event.target);
      },
      [handleItemEnter]
    );

